#!/usr/bin/env python3
# Original reimplementation of the Doxygen 1.17.0 command line interface,
# written from scratch based on behavioral observation of the reference
# executable. It supports generating template configuration files, updating
# and comparing configuration files, generating layout/style templates and
# producing documentation for the (empty project) default configuration.

import os
import re
import sys
import zlib
import base64

VERSION = "1.17.0"
VERSION_FULL = "1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)"

# RESOURCE_DATA and TAGDATA are injected by the build step.
RESOURCE_DATA = {}
TAGDATA = {}

_res_cache = {}


def get_resource(name):
    if name not in _res_cache:
        _res_cache[name] = zlib.decompress(
            base64.b85decode(RESOURCE_DATA[name])).decode('utf-8')
    return _res_cache[name]


def get_resource_bytes(name):
    return get_resource(name).encode('utf-8')


# ---------------------------------------------------------------------------
# Template / configuration model
# ---------------------------------------------------------------------------

class Tag:
    __slots__ = ('name', 'raw_lines', 'default', 'section')

    def __init__(self, name, raw_lines, section):
        self.name = name
        self.raw_lines = raw_lines      # default value lines as in the template
        self.default = None             # parsed default value (list of tokens)
        self.section = section


class Section:
    __slots__ = ('lines', 'tags')

    def __init__(self, lines):
        self.lines = lines              # the 3 separator/comment lines
        self.tags = []


class Template:
    def __init__(self):
        text = get_resource('Doxyfile.template')
        self.text = text
        lines = text.split('\n')
        # The file ends with a trailing newline; drop the artificial last ''.
        if lines and lines[-1] == '':
            lines.pop()
        self.header = []                # lines before the first section
        self.sections = []
        self.tags = []                  # all tags in order
        self.tagmap = {}
        i = 0
        n = len(lines)
        # header: everything up to the first section separator
        while i < n and not re.match(r'^#-+$', lines[i]):
            self.header.append(lines[i])
            i += 1
        cur = None
        pending_comment = []
        while i < n:
            line = lines[i]
            if re.match(r'^#-+$', line):
                # section separator block: 3 lines
                sec = Section(lines[i:i + 3])
                self.sections.append(sec)
                cur = sec
                i += 3
                pending_comment = []
                continue
            m = re.match(r'^([A-Z][A-Z0-9_]*) *=', line)
            if m:
                block = [line]
                i += 1
                while block[-1].rstrip().endswith('\\') and i < n:
                    block.append(lines[i])
                    i += 1
                tag = Tag(m.group(1), block, cur)
                if cur is not None:
                    cur.tags.append(tag)
                self.tags.append(tag)
                self.tagmap[tag.name] = tag
                pending_comment = []
                continue
            i += 1


TEMPLATE = None


def template():
    global TEMPLATE
    if TEMPLATE is None:
        TEMPLATE = Template()
        # parse default values
        for tag in TEMPLATE.tags:
            joined = tag.raw_lines[0]
            for cont in tag.raw_lines[1:]:
                joined = joined.rstrip()
                if joined.endswith('\\'):
                    joined = joined[:-1]
                joined += ' ' + cont.strip()
            value = joined.split('=', 1)[1]
            tag.default = split_values(value)
    return TEMPLATE


def bool_tags():
    return set(TAGDATA['BOOL_TAGS'])


def list_tags():
    return set(TAGDATA['LIST_TAGS'])


def int_tags():
    return TAGDATA['INT_TAGS']


def enum_tags():
    return TAGDATA['ENUM_TAGS']


OBSOLETE_TAGS = {
    'CLASS_DIAGRAMS', 'COLS_IN_ALPHA_INDEX', 'DETAILS_AT_TOP',
    'HTML_ALIGN_MEMBERS', 'MAX_DOT_GRAPH_WIDTH', 'MAX_DOT_GRAPH_HEIGHT',
    'MSCGEN_PATH', 'PERL_PATH', 'SHOW_DIRECTORIES', 'SYMBOL_CACHE_SIZE',
    'USE_INLINE_TREES', 'XML_DTD', 'XML_SCHEMA',
}


# ---------------------------------------------------------------------------
# Config value parsing helpers
# ---------------------------------------------------------------------------

def strip_comment(line):
    """Remove an unquoted trailing # comment from a config line."""
    in_quote = False
    i = 0
    while i < len(line):
        c = line[i]
        if c == '\\' and in_quote and i + 1 < len(line) and line[i + 1] == '"':
            i += 2
            continue
        if c == '"':
            in_quote = not in_quote
        elif c == '#' and not in_quote:
            return line[:i]
        i += 1
    return line


def split_values(s):
    """Split a config value string into tokens, honoring double quotes."""
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        while i < n and s[i] in ' \t':
            i += 1
        if i >= n:
            break
        tok = []
        while i < n and s[i] not in ' \t':
            c = s[i]
            if c == '"':
                i += 1
                while i < n and s[i] != '"':
                    if s[i] == '\\' and i + 1 < n and s[i + 1] == '"':
                        tok.append('"')
                        i += 2
                    else:
                        tok.append(s[i])
                        i += 1
                if i < n:
                    i += 1  # skip closing quote
            else:
                tok.append(c)
                i += 1
        tokens.append(''.join(tok))
    return tokens


def subst_env(s):
    def rep(m):
        return os.environ.get(m.group(1), '')
    return re.sub(r'\$\(([A-Za-z_][A-Za-z0-9_.-]*)\)', rep, s)


# ---------------------------------------------------------------------------
# Config file parsing
# ---------------------------------------------------------------------------

class Config:
    def __init__(self):
        self.values = {}          # name -> list of tokens (user supplied)
        self.provided = set()     # tags explicitly present in the file
        self.warnings = []        # parse/validation warnings (stderr text)


def _parse_config_text(cfg, text, fname, noenv, depth=0):
    tmpl = template()
    # join continuation lines, tracking the starting line number
    raw_lines = text.split('\n')
    logical = []  # (lineno, text)
    i = 0
    n = len(raw_lines)
    while i < n:
        line = raw_lines[i]
        start = i + 1
        stripped = strip_comment(line).rstrip()
        while stripped.endswith('\\'):
            i += 1
            if i >= n:
                break
            stripped = stripped[:-1] + ' ' + strip_comment(raw_lines[i]).strip()
            stripped = stripped.rstrip()
        logical.append((start, stripped))
        i += 1
    for lineno, line in logical:
        if not line.strip():
            continue
        m = re.match(r'^@INCLUDE\s*=\s*(.*)$', line)
        if m:
            inc = m.group(1).strip().strip('"')
            if not os.path.isabs(inc) and fname not in ('-', ''):
                inc = os.path.join(os.path.dirname(fname), inc)
            try:
                with open(inc, 'r', encoding='utf-8', errors='replace') as f:
                    _parse_config_text(cfg, f.read(), inc, noenv, depth + 1)
            except OSError:
                cfg.warnings.append(
                    "warning: @INCLUDE file '%s' not found, skipping..." %
                    m.group(1).strip().strip('"'))
            continue
        m = re.match(r'^([A-Za-z][A-Za-z0-9_]*)\s*(\+=|=)\s*(.*)$', line)
        if not m:
            continue
        name, op, valstr = m.group(1), m.group(2), m.group(3)
        if not noenv:
            valstr = subst_env(valstr)
        if name in OBSOLETE_TAGS:
            cfg.warnings.append(
                "warning: Tag '%s' at line %d of file '%s' has become obsolete.\n"
                "         To avoid this warning please remove this line from "
                "your configuration file or upgrade it using \"doxygen -u\""
                % (name, lineno, fname))
            continue
        if name not in tmpl.tagmap:
            cfg.warnings.append(
                "warning: ignoring unsupported tag '%s' at line %d, file %s"
                % (name, lineno, fname))
            continue
        tokens = split_values(valstr)
        if op == '+=':
            if name not in list_tags():
                cfg.warnings.append(
                    "warning: operator += not supported for '%s +='. "
                    "Ignoring line at line %d, file %s" % (name, lineno, fname))
                continue
            base = cfg.values.get(name)
            if base is None:
                base = list(tmpl.tagmap[name].default)
            cfg.values[name] = base + tokens
        else:
            cfg.values[name] = tokens
        cfg.provided.add(name)


def parse_config_file(fname, noenv=False):
    cfg = Config()
    if fname == '-':
        text = sys.stdin.read()
    else:
        with open(fname, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
    _parse_config_text(cfg, text, fname, noenv)
    validate_config(cfg)
    return cfg


def validate_config(cfg):
    """Validate user supplied values; warnings in template order."""
    tmpl = template()
    for tag in tmpl.tags:
        name = tag.name
        if name not in cfg.provided:
            continue
        tokens = cfg.values[name]
        value = tokens[0] if tokens else ''
        if name in bool_tags():
            if value.upper() not in ('YES', 'NO', 'TRUE', 'FALSE', '1', '0',
                                     ''):
                cfg.warnings.append(
                    "warning: argument '%s' for option %s is not a valid "
                    "boolean value\nUsing the default: %s!" %
                    (value, name, ' '.join(tag.default)))
                cfg.values[name] = list(tag.default)
        elif name in int_tags():
            lo, hi = int_tags()[name]
            ok = re.match(r'^-?[0-9]+$', value) is not None
            if ok:
                v = int(value)
                ok = lo <= v <= hi
            if not ok:
                cfg.warnings.append(
                    "warning: argument '%s' for option %s is not a valid "
                    "number in the range [%d..%d]!\nUsing the default: %s!" %
                    (value, name, lo, hi, ' '.join(tag.default)))
                cfg.values[name] = list(tag.default)
        elif name in enum_tags():
            allowed = enum_tags()[name]
            if value not in allowed:
                cfg.warnings.append(
                    "warning: argument '%s' for option %s is not a valid "
                    "enum value\nUsing the default: %s!" %
                    (value, name, ' '.join(tag.default)))
                cfg.values[name] = list(tag.default)


def effective_value(cfg, name):
    tmpl = template()
    if cfg and name in cfg.values:
        return cfg.values[name]
    return list(tmpl.tagmap[name].default)


def effective_string(cfg, name):
    return ' '.join(effective_value(cfg, name))


def effective_bool(cfg, name):
    return effective_string(cfg, name).upper() in ('YES', 'TRUE', '1')


# ---------------------------------------------------------------------------
# Config value formatting (for -x and -u output)
# ---------------------------------------------------------------------------

def quote_value(s):
    if s == '' or re.search(r'[\s"]', s):
        return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
    return s


def format_tag_lines(name, tokens):
    """Format a tag assignment the way doxygen writes it."""
    head = name.ljust(23) + '='
    if not tokens:
        return [head]
    if name in list_tags():
        lines = []
        for i, tok in enumerate(tokens):
            piece = quote_value(tok)
            if i == 0:
                line = head + ' ' + piece
            else:
                line = ' ' * 25 + piece
            if i < len(tokens) - 1:
                line += ' \\'
            lines.append(line)
        return lines
    value = ' '.join(tokens)
    return [head + ' ' + quote_value(value)]


# ---------------------------------------------------------------------------
# Config output writers
# ---------------------------------------------------------------------------

def config_to_short_text(cfg=None):
    """-s style output: header + section separators + tag lines only."""
    tmpl = template()
    out = ['# Doxyfile %s' % VERSION, '']
    for sec in tmpl.sections:
        out.extend(sec.lines)
        for tag in sec.tags:
            if cfg is not None and tag.name in cfg.provided:
                out.extend(format_tag_lines(tag.name, cfg.values[tag.name]))
            else:
                out.extend(tag.raw_lines)
    return '\n'.join(out) + '\n'


def config_to_full_text(cfg=None):
    """Full template output, optionally with user values substituted."""
    tmpl = template()
    if cfg is None:
        return tmpl.text
    replace = {}
    for tag in tmpl.tags:
        if tag.name in cfg.provided:
            replace[id(tag)] = format_tag_lines(tag.name,
                                                cfg.values[tag.name])
    out = list(tmpl.header)
    for sec in tmpl.sections:
        out.extend(sec.lines)
        # regenerate section body: walk the raw template lines of this section
        # We rebuild from raw template text: comment lines are kept verbatim,
        # tag value blocks are replaced where the user provided a value.
        # To do so we track positions via the original template lines.
        out.extend(_section_body_lines(sec, replace))
    return '\n'.join(out) + '\n'


def _section_body_lines(sec, replace):
    """Reconstruct the raw lines of a section body from the template."""
    tmpl = template()
    # find the raw text: we stored only tag blocks, so rebuild by scanning the
    # template text again for this section.
    # Simpler: the whole template text lines are re-scanned once here.
    if not hasattr(tmpl, '_lines'):
        lines = tmpl.text.split('\n')
        if lines and lines[-1] == '':
            lines.pop()
        tmpl._lines = lines
    lines = tmpl._lines
    # locate this section in the raw lines by matching its separator block
    # and the previous section's end. Sections are in order; use an index.
    if not hasattr(tmpl, '_sec_spans'):
        spans = []
        i = 0
        n = len(lines)
        while i < n and not re.match(r'^#-+$', lines[i]):
            i += 1
        while i < n:
            start = i
            i += 3  # separator block
            # body until next separator or EOF
            while i < n and not re.match(r'^#-+$', lines[i]):
                i += 1
            spans.append((start, i))
        tmpl._sec_spans = spans
    idx = tmpl.sections.index(sec)
    start, end = tmpl._sec_spans[idx]
    body = lines[start + 3:end]
    # Replace tag blocks
    out = []
    i = 0
    while i < len(body):
        line = body[i]
        m = re.match(r'^([A-Z][A-Z0-9_]*) *=', line)
        if m:
            block = [line]
            i += 1
            while block[-1].rstrip().endswith('\\') and i < len(body):
                block.append(body[i])
                i += 1
            name = m.group(1)
            tag = tmpl.tagmap.get(name)
            if tag is not None and id(tag) in replace:
                out.extend(replace[id(tag)])
            else:
                out.extend(block)
        else:
            out.append(line)
            i += 1
    return out


def diff_text(cfg):
    """-x output: difference with default configuration."""
    tmpl = template()
    out = ['# Difference with default Doxyfile %s' % VERSION_FULL]
    for tag in tmpl.tags:
        if tag.name in cfg.provided:
            if cfg.values[tag.name] != tag.default:
                out.extend(format_tag_lines(tag.name, cfg.values[tag.name]))
    return '\n'.join(out) + '\n'


# ---------------------------------------------------------------------------
# Message helpers
# ---------------------------------------------------------------------------

def err(msg):
    sys.stderr.write(msg + '\n')


def print_warnings(cfg):
    for w in cfg.warnings:
        sys.stderr.write(w + '\n')


def usage(prog):
    text = get_resource('usage.txt')
    # usage.txt was captured with the reference path; substitute argv[0]
    text = text.replace('/workspace/executable', prog)
    sys.stdout.write(text)


def version():
    sys.stdout.write(VERSION_FULL + '\n')


def version_ext():
    sys.stdout.write(VERSION_FULL + '\n    with sqlite3 3.42.0.\n')


# ---------------------------------------------------------------------------
# File writing helpers
# ---------------------------------------------------------------------------

def write_file(path, data):
    if path == '-':
        if isinstance(data, str):
            sys.stdout.write(data)
        else:
            sys.stdout.buffer.write(data)
        return True
    try:
        mode = 'w' if isinstance(data, str) else 'wb'
        with open(path, mode) as f:
            f.write(data)
        return True
    except OSError:
        err("error: cannot open file '%s' for writing" % path)
        return False


# ---------------------------------------------------------------------------
# CLI mode implementations
# ---------------------------------------------------------------------------

def do_generate_config(name, short):
    if name is None:
        name = 'Doxyfile'
    text = config_to_short_text() if short else config_to_full_text()
    if name == '-':
        sys.stdout.write(text)
        return 0
    if not write_file(name, text):
        return 1
    sys.stdout.write(
        "\n\nConfiguration file '%s' created.\n\n"
        "Now edit the configuration file and enter\n\n"
        "  doxygen %s\n\n"
        "to generate the documentation for your project\n\n" % (name, name))
    return 0


def do_update_config(name, short):
    if name is None:
        name = 'Doxyfile'
    if name != '-' and not os.path.exists(name):
        err("error: configuration file %s not found!" % name)
        usage(sys.argv[0])
        return 1
    cfg = parse_config_file(name)
    print_warnings(cfg)
    text = config_to_short_text(cfg) if short else config_to_full_text(cfg)
    if name == '-':
        sys.stdout.write(text)
        return 0
    # make a backup copy
    try:
        with open(name, 'rb') as f:
            old = f.read()
        with open(name + '.bak', 'wb') as f:
            f.write(old)
    except OSError:
        pass
    if not write_file(name, text):
        return 1
    sys.stdout.write("\n\nConfiguration file '%s' updated.\n\n" % name)
    return 0


def do_diff_config(name, noenv):
    if name is None:
        name = 'Doxyfile'
        if not os.path.exists(name):
            err("error: Doxyfile not found and no input file specified!")
            usage(sys.argv[0])
            return 1
    elif name != '-' and not os.path.exists(name):
        err("error: configuration file %s not found!" % name)
        usage(sys.argv[0])
        return 1
    cfg = parse_config_file(name, noenv)
    print_warnings(cfg)
    sys.stdout.write(diff_text(cfg))
    return 0


def do_layout(name):
    if name is None:
        name = 'DoxygenLayout.xml'
    if not write_file(name, get_resource('layout.xml')):
        return 1
    return 0


def do_write_template(args):
    if not args:
        err('error: option "-w" is missing format specifier rtf, html or latex')
        return 1
    fmt = args[0]
    if fmt not in ('rtf', 'html', 'latex'):
        err('error: Illegal format specifier "%s": should be one of rtf, '
            'html or latex' % fmt)
        return 1
    rest = args[1:]
    if fmt == 'rtf':
        if not rest:
            err('error: option "-w rtf" is missing a style sheet file name')
            return 1
        return 0 if write_file(rest[0], get_resource('rtfstyle.rtf')) else 1
    # html / latex
    if len(rest) < 3:
        err('error: option "-w %s" does not have enough arguments' % fmt)
        return 1
    if len(rest) >= 4:
        cfgname = rest[3]
        if cfgname != '-' and not os.path.exists(cfgname):
            err("error: file '%s' not found or could not be opened"
                % cfgname)
            err("Exiting...")
            return 1
    if fmt == 'html':
        files = ('html_header.html', 'html_footer.html', 'html_style.css')
    else:
        files = ('latex_header.tex', 'latex_footer.tex', 'latex_style.sty')
    for path, res in zip(rest[:3], files):
        if not write_file(path, get_resource(res)):
            return 1
    return 0


def do_extensions(args):
    if not args:
        err('error: option "-e" is missing format specifier rtf.')
        return 1
    if args[0] != 'rtf':
        err('error: option "-e" has invalid format specifier.')
        return 1
    if len(args) < 2:
        err('error: option "-e rtf" is missing an extensions file name')
        return 1
    return 0 if write_file(args[1], get_resource('rtfext.rtf')) else 1


def do_list_output(args):
    if not args:
        err('error: option "-f" is missing list specifier.')
        return 1
    if args[0] != 'emoji':
        err('error: option "-f" has invalid list specifier.')
        return 1
    if len(args) < 2:
        err('error: option "-f emoji" is missing an output file name')
        return 1
    return 0 if write_file(args[1], get_resource('emoji.txt')) else 1


DEBUG_LEVELS = [
    'alias', 'cite', 'commentcnv', 'commentscan', 'entries', 'extcmd',
    'filteroutput', 'formula', 'fortranfixed2free', 'layout', 'lex',
    'lex:code', 'lex:commentcnv', 'lex:commentscan', 'lex:configimpl',
    'lex:constexp', 'lex:declinfo', 'lex:defargs', 'lex:doctokenizer',
    'lex:fortrancode', 'lex:fortranscanner', 'lex:lexcode', 'lex:lexscanner',
    'lex:pre', 'lex:pycode', 'lex:pyscanner', 'lex:scanner', 'lex:sqlcode',
    'lex:vhdlcode', 'lex:xml', 'lex:xmlcode', 'markdown', 'nolineno',
    'plantuml', 'preprocessor', 'printtree', 'qhp', 'rtf', 'sections',
    'stderr', 'tag', 'time',
]


# ---------------------------------------------------------------------------
# Documentation generation run
# ---------------------------------------------------------------------------

