def escape_html(s):
    return (s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
             .replace('"', '&quot;'))


_LATEX_CHAR_MAP = {
    '\\': '\\textbackslash{}',
    '_': '\\_',
    '%': '\\%',
    '&': '\\&',
    '#': '\\+\\#',
    '$': '\\$',
    '{': '\\{',
    '}': '\\}',
    '~': '\\texorpdfstring{$\\sim$}{\\string~}',
    '^': '\\texorpdfstring{$^\\wedge$}{\\string^}',
    '|': '\\texorpdfstring{$\\vert$}{|}',
    "'": '\\textquotesingle{}',
    '"': '"{}',
    '<': '$<$',
    '>': '$>$',
    '*': '\\texorpdfstring{$\\ast$}{*}',
    '-': '-\\/',
    '.': '.\\+',
    '/': '/\\+',
    '[': '\\+[',
    ']': ']\\+',
}


def escape_latex(s):
    out = []
    for i, c in enumerate(s):
        rep = _LATEX_CHAR_MAP.get(c, c)
        # quirk: an uppercase letter directly inside <...> or after a quote
        # gets a \+ prefix
        if ('A' <= c <= 'Z') and i > 0 and i + 1 < len(s):
            if s[i - 1] == '<' and s[i + 1] == '>':
                rep = '\\+' + c
            elif s[i - 1] == '"' and s[i + 1] == '"':
                rep = '\\+' + c
        out.append(rep)
    return ''.join(out)


def patch_index_html(text, name, number, brief):
    ename = escape_html(name)
    out = text
    if name:
        out = out.replace('<title>My Project: Main Page</title>',
                          '<title>%s: Main Page</title>' % ename)
        proj = '<div id="projectname">%s' % ename
        if number:
            proj += ('<span id="projectnumber">&#160;%s</span>'
                     % escape_html(number))
        proj += '\n   </div>'
        if brief:
            proj += ('\n   <div id="projectbrief">%s</div>'
                     % escape_html(brief))
        out = out.replace('<div id="projectname">My Project\n   </div>',
                          proj)
        out = out.replace(
            '<div class="headertitle"><div class="title">'
            'My Project Documentation</div></div>',
            '<div class="headertitle"><div class="title">'
            '%s Documentation</div></div>' % ename)
    else:
        out = out.replace('<title>My Project: Main Page</title>',
                          '<title>Main Page</title>')
        out = out.replace('   <div id="projectname">My Project\n'
                          '   </div>\n', '')
        out = out.replace(
            '<div class="headertitle"><div class="title">'
            'My Project Documentation</div></div>',
            '<div class="headertitle"><div class="title">'
            'Documentation</div></div>')
    return out


def patch_navtreedata(text, name):
    return text.replace('[ "My Project", "index.html", ]',
                        '[ "%s", "index.html", ]' % escape_html(name))


def patch_refman(text, name, number, brief):
    out = text
    out = out.replace('pdftitle={My Project},%',
                      'pdftitle={%s},%%' % escape_latex(name))
    out = out.replace('pdfsubject={}%',
                      'pdfsubject={%s},%%' % escape_latex(brief))
    title = '  {\\Large My Project}\\\\\n'
    repl = '  {\\Large %s}\\\\\n' % escape_latex(name)
    if number:
        repl += '  [1ex]\\large %s \\\\\n' % escape_latex(number)
    out = out.replace(title, repl)
    return out


def gather_input_dirs(cfg):
    """Return (dirs, files, missing) from the INPUT tag."""
    inputs = effective_value(cfg, 'INPUT')
    if not inputs:
        inputs = ['']
    dirs, files, missing = [], [], []
    for item in inputs:
        path = item if item else '.'
        if os.path.isdir(path):
            dirs.append(os.path.abspath(path))
        elif os.path.isfile(path):
            files.append(path)
        else:
            missing.append(item)
    return dirs, files, missing


def run_generate(cfg, quiet):
    # config check phase: a few file existence checks
    for tag, kind in (('HTML_HEADER', 'header'), ('HTML_FOOTER', 'footer'),
                      ('LATEX_HEADER', 'header'), ('LATEX_FOOTER', 'footer')):
        val = effective_string(cfg, tag)
        if val and not os.path.exists(val):
            err("error: tag %s: %s file '%s' does not exist" % (tag, kind,
                                                                val))
            err("Exiting...")
            return 1

    dirs, files, missing = gather_input_dirs(cfg)

    warnings = []
    for m in missing:
        warnings.append("warning: tag INPUT: input source '%s' does not exist"
                        % m)
        warnings.append("warning: source '%s' is not a readable file or "
                        "directory... skipping." % m)
    no_input = not dirs and not files
    if no_input:
        warnings.append("warning: No files to be processed, please check "
                        "your settings, in particular INPUT, FILE_PATTERNS, "
                        "and RECURSIVE")
    for w in warnings:
        err(w)

    if not quiet:
        log = [RUN_LOG_HEAD]
        for d in dirs:
            log.append('Searching for files in directory %s' % d)
        log.append(RUN_LOG_TAIL)
        sys.stdout.write('\n'.join(log) + '\n')

    outdir = effective_string(cfg, 'OUTPUT_DIRECTORY')
    if effective_bool(cfg, 'GENERATE_HTML'):
        html_dir = os.path.join(outdir, effective_string(cfg, 'HTML_OUTPUT')
                                or 'html')
        write_html_output(cfg, html_dir)
    if effective_bool(cfg, 'GENERATE_LATEX'):
        latex_dir = os.path.join(outdir, effective_string(cfg, 'LATEX_OUTPUT')
                                 or 'latex')
        write_latex_output(cfg, latex_dir)
    return 0


def write_html_output(cfg, html_dir):
    name = effective_string(cfg, 'PROJECT_NAME')
    number = effective_string(cfg, 'PROJECT_NUMBER')
    brief = effective_string(cfg, 'PROJECT_BRIEF')
    files = ['clipboard.js', 'cookie.js', 'doxygen.css', 'doxygen.svg',
             'doxygen_crawl.html', 'dynsections.js', 'index.html', 'menu.js',
             'menudata.js', 'navtree.css', 'navtree.js', 'navtreedata.js',
             'navtreeindex0.js', 'tabs.css', 'search/search.css',
             'search/search.js', 'search/searchdata.js']
    for rel in files:
        dest = os.path.join(html_dir, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        data = get_resource('gen/html/' + rel)
        if rel == 'index.html':
            data = patch_index_html(data, name, number, brief)
        elif rel == 'navtreedata.js':
            data = patch_navtreedata(data, name)
        with open(dest, 'w') as f:
            f.write(data)


def write_latex_output(cfg, latex_dir):
    name = effective_string(cfg, 'PROJECT_NAME')
    number = effective_string(cfg, 'PROJECT_NUMBER')
    brief = effective_string(cfg, 'PROJECT_BRIEF')
    os.makedirs(latex_dir, exist_ok=True)
    for rel in ('Makefile', 'doxygen.sty', 'etoc_doxygen.sty'):
        with open(os.path.join(latex_dir, rel), 'w') as f:
            f.write(get_resource('gen/latex/' + rel))
    refman = patch_refman(get_resource('gen/latex/refman.tex'), name, number,
                          brief)
    with open(os.path.join(latex_dir, 'refman.tex'), 'w') as f:
        f.write(refman)


# ---------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------

def main(argv):
    prog = argv[0]
    args = argv[1:]
    short = False
    quiet = False
    mode = None
    mode_arg = None
    positional = []
    w_args = None
    i = 0
    while i < len(args):
        a = args[i]
        if a == '-s':
            short = True
        elif a == '-q':
            quiet = True
        elif a == '-v':
            version()
            return 0
        elif a == '-V':
            version_ext()
            return 0
        elif a in ('-h', '-?', '--help'):
            usage(prog)
            return 0
        elif a == '-d':
            if i + 1 < len(args):
                lvl = args[i + 1]
                if lvl in DEBUG_LEVELS:
                    i += 1  # consume, debug output unsupported but accepted
                else:
                    err('option "-d" has unknown debug specifier: "%s".' % lvl)
                    sys.stdout.write(get_resource('devlist.txt'))
                    return 1
            else:
                sys.stdout.write(get_resource('devlist.txt'))
                return 0
        elif a in ('-m', '-b'):
            pass
        elif a == '-g':
            mode = 'gen'
            if i + 1 < len(args) and not args[i + 1].startswith('-') or \
                    (i + 1 < len(args) and args[i + 1] == '-'):
                if i + 1 < len(args) and (not args[i + 1].startswith('-')
                                          or args[i + 1] == '-'):
                    mode_arg = args[i + 1]
                    i += 1
        elif a == '-u':
            mode = 'upd'
            if i + 1 < len(args) and (not args[i + 1].startswith('-')
                                      or args[i + 1] == '-'):
                mode_arg = args[i + 1]
                i += 1
        elif a == '-l':
            mode = 'layout'
            if i + 1 < len(args) and (not args[i + 1].startswith('-')
                                      or args[i + 1] == '-'):
                mode_arg = args[i + 1]
                i += 1
        elif a == '-x':
            mode = 'diff'
        elif a == '-x_noenv':
            mode = 'diff_noenv'
        elif a == '-w':
            mode = 'write'
            w_args = args[i + 1:]
            i = len(args)
            break
        elif a == '-e':
            mode = 'ext'
            w_args = args[i + 1:]
            i = len(args)
            break
        elif a == '-f':
            mode = 'flist'
            w_args = args[i + 1:]
            i = len(args)
            break
        elif a.startswith('-') and a != '-':
            err('error: Unknown option "%s"' % a)
            usage(prog)
            return 1
        else:
            positional.append(a)
        i += 1

    if mode == 'gen':
        return do_generate_config(mode_arg, short)
    if mode == 'upd':
        return do_update_config(mode_arg, short)
    if mode == 'layout':
        return do_layout(mode_arg)
    if mode == 'diff' or mode == 'diff_noenv':
        name = positional[0] if positional else None
        return do_diff_config(name, mode == 'diff_noenv')
    if mode == 'write':
        return do_write_template(w_args)
    if mode == 'ext':
        return do_extensions(w_args)
    if mode == 'flist':
        return do_list_output(w_args)

    # documentation generation run
    name = positional[0] if positional else 'Doxyfile'
    explicit = bool(positional)
    if name != '-' and not os.path.exists(name):
        if explicit:
            err("error: configuration file %s not found!" % name)
            usage(prog)
            return 1
        err("error: Doxyfile not found and no input file specified!")
        usage(prog)
        return 0
    try:
        cfg = parse_config_file(name)
    except OSError:
        err("error: cannot open configuration file %s" % name)
        return 1
    print_warnings(cfg)
    return run_generate(cfg, quiet or effective_bool(cfg, 'QUIET'))


if __name__ == '__main__':
    sys.exit(main(sys.argv))

